require __DIR__.'/app/bootstrap.php';$u=require_login();$orderId=(int)($_GET['order']??0);$itemId=(int)($_GET['item']??0);$o=store_order($orderId);if(!$o||(int)$o['buyer_user_id']!==(int)$u['id']||$o['payment_status']!=='paid'){http_response_code(403);exit('Download unavailable.');}$q=db()->prepare("SELECT oi.*,p.digital_file_path FROM store_order_items oi JOIN store_products p ON p.id=oi.product_id WHERE oi.id=? AND oi.order_id=? AND oi.product_type='digital' LIMIT 1");$q->execute([$itemId,$orderId]);$it=$q->fetch();if(!$it||!$it['digital_file_path']){http_response_code(404);exit('File not found.');}$base=realpath(__DIR__.'/storage/digital_products');$file=realpath(__DIR__.'/'.ltrim($it['digital_file_path'],'/'));if(!$base||!$file||!str_starts_with($file,$base.DIRECTORY_SEPARATOR)||!is_file($file)){http_response_code(404);exit('File not found.');}header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.basename($file).'"');header('Content-Length: '.filesize($file));readfile($file);exit;
